192	static int cvi_eth_pm_suspend(struct device *dev)
193	{
194		struct net_device *ndev = dev_get_drvdata(dev);
195		struct stmmac_priv *priv = netdev_priv(ndev);
196	
197		if (!priv->reg_ctx) {
198			priv->reg_ctx = devm_kzalloc(priv->device, sizeof(struct stmmac_reg_context), GFP_KERNEL);
199			if (!priv->reg_ctx)
200				return -ENOMEM;
201		}
202		priv->reg_ctx->ctrl = readl(priv->ioaddr + GMAC_CONTROL);
203		priv->reg_ctx->frame_filter = readl(priv->ioaddr + GMAC_FRAME_FILTER);
204		priv->reg_ctx->hash_high = readl(priv->ioaddr + GMAC_HASH_HIGH);
205		priv->reg_ctx->hash_low = readl(priv->ioaddr + GMAC_HASH_LOW);
206		priv->reg_ctx->mii_addr = readl(priv->ioaddr + GMAC_MII_ADDR);
207		priv->reg_ctx->mii_data = readl(priv->ioaddr + GMAC_MII_DATA);
208		priv->reg_ctx->flow_ctrl = readl(priv->ioaddr + GMAC_FLOW_CTRL);
209		priv->reg_ctx->vlan_tag = readl(priv->ioaddr + GMAC_VLAN_TAG);
210		priv->reg_ctx->debug = readl(priv->ioaddr + GMAC_DEBUG);
211		priv->reg_ctx->wakeup_fileter = readl(priv->ioaddr + GMAC_WAKEUP_FILTER);
212		priv->reg_ctx->lpi_ctrl_status = readl(priv->ioaddr + LPI_CTRL_STATUS);
213		priv->reg_ctx->lpi_timer_ctrl = readl(priv->ioaddr + LPI_TIMER_CTRL);
214		priv->reg_ctx->int_mask = readl(priv->ioaddr + GMAC_INT_MASK);
215		priv->reg_ctx->mac_addr0_high = readl(priv->ioaddr + GMAC_MAC_ADDR0_HIGH);
216		priv->reg_ctx->mac_addr0_low = readl(priv->ioaddr + GMAC_MAC_ADDR0_LOW);
217		priv->reg_ctx->pcs_base = readl(priv->ioaddr + GMAC_PCS_BASE);
218		priv->reg_ctx->mmc_ctrl = readl(priv->ioaddr + GMAC_MMC_CTRL);
219		priv->reg_ctx->mmc_rx_intr_mask = readl(priv->ioaddr + GMAC_MMC_RX_INTR_MASK);
220		priv->reg_ctx->mmc_tx_intr_mask = readl(priv->ioaddr + GMAC_MMC_TX_INTR_MASK);
221		priv->reg_ctx->mmc_ipc_rx_intr_mask = readl(priv->ioaddr + GMAC_MMC_IPC_RX_INTR_MASK);
222		priv->reg_ctx->mmc_rx_csum_offload = readl(priv->ioaddr + GMAC_MMC_RX_CSUM_OFFLOAD);
223		priv->reg_ctx->dma_bus_mode = readl(priv->ioaddr + DMA_BUS_MODE);
224		priv->reg_ctx->dma_rx_base_addr = readl(priv->ioaddr + DMA_RCV_BASE_ADDR);
225		priv->reg_ctx->dma_tx_base_addr = readl(priv->ioaddr + DMA_TX_BASE_ADDR);
226		priv->reg_ctx->dma_ctrl = readl(priv->ioaddr + DMA_CONTROL);
227		priv->reg_ctx->dma_intr_ena = readl(priv->ioaddr + DMA_INTR_ENA);
228		priv->reg_ctx->dma_rx_watchdog = readl(priv->ioaddr + DMA_RX_WATCHDOG);
229		priv->reg_ctx->dma_axi_bus_mode = readl(priv->ioaddr + DMA_AXI_BUS_MODE);
230	
231		return 0;
232	}
