1825	
1826		if (dm_gpio_is_valid(&eqos->phy_reset_gpio))
1827			dm_gpio_free(dev, &eqos->phy_reset_gpio);
1828	
1829		debug("%s: OK\n", __func__);
1830		return 0;
1831	}
