1833	static int eqos_probe(struct udevice *dev)
1834	{
1835		struct eqos_priv *eqos = dev_get_priv(dev);
1836		int ret;
1837	
1838		debug("%s(dev=%p):\n", __func__, dev);
1839	
1840		eqos->dev = dev;
1841		eqos->config = (void *)dev_get_driver_data(dev);
1842	
1843		eqos->regs = dev_read_addr(dev);
1844		if (eqos->regs == FDT_ADDR_T_NONE) {
1845			pr_err("dev_read_addr() failed");
1846			return -ENODEV;
1847		}
1848		eqos->mac_regs = (void *)(eqos->regs + EQOS_MAC_REGS_BASE);
1849		eqos->mtl_regs = (void *)(eqos->regs + EQOS_MTL_REGS_BASE);
1850		eqos->dma_regs = (void *)(eqos->regs + EQOS_DMA_REGS_BASE);
1851		eqos->tegra186_regs = (void *)(eqos->regs + EQOS_TEGRA186_REGS_BASE);
1852	
1853		ret = eqos_probe_resources_core(dev);
1854		if (ret < 0) {
1855			pr_err("eqos_probe_resources_core() failed: %d", ret);
1856			return ret;
1857		}
1858	
1859		ret = eqos->config->ops->eqos_probe_resources(dev);
1860		if (ret < 0) {
1861			pr_err("eqos_probe_resources() failed: %d", ret);
1862			goto err_remove_resources_core;
1863		}
1864	
1865	#ifdef CONFIG_DM_ETH_PHY
1866		eqos->mii = eth_phy_get_mdio_bus(dev);
1867	#endif
1868		if (!eqos->mii) {
1869			eqos->mii = mdio_alloc();
1870			if (!eqos->mii) {
1871				pr_err("mdio_alloc() failed");
1872				ret = -ENOMEM;
1873				goto err_remove_resources_tegra;
1874			}
1875			eqos->mii->read = eqos_mdio_read;
1876			eqos->mii->write = eqos_mdio_write;
1877			eqos->mii->priv = eqos;
1878			strcpy(eqos->mii->name, dev->name);
1879	
1880			ret = mdio_register(eqos->mii);
1881			if (ret < 0) {
1882				pr_err("mdio_register() failed: %d", ret);
1883				goto err_free_mdio;
1884			}
1885		}
1886	
1887	#ifdef CONFIG_DM_ETH_PHY
1888		eth_phy_set_mdio_bus(dev, eqos->mii);
1889	#endif
1890	
1891		debug("%s: OK\n", __func__);
1892		return 0;
1893	
1894	err_free_mdio:
1895		mdio_free(eqos->mii);
1896	err_remove_resources_tegra:
1897		eqos->config->ops->eqos_remove_resources(dev);
1898	err_remove_resources_core:
1899		eqos_remove_resources_core(dev);
1900	
1901		debug("%s: returns %d\n", __func__, ret);
1902		return ret;
1903	}
1904	
1905	static int eqos_remove(struct udevice *dev)
1906	{
1907		struct eqos_priv *eqos = dev_get_priv(dev);
1908	
1909		debug("%s(dev=%p):\n", __func__, dev);
1910	
1911		mdio_unregister(eqos->mii);
1912		mdio_free(eqos->mii);
1913		eqos->config->ops->eqos_remove_resources(dev);
1914	
1915		eqos_probe_resources_core(dev);
1916	
1917		debug("%s: OK\n", __func__);
1918		return 0;
1919	}
