107	static void reset_assert(unsigned int id)
108	{
109	  unsigned int bank = id / 32;
110	  unsigned int bit = id % 32;
111	  uint32_t reg = getreg32(REG_RESET_BANK(bank));
112	
113	  putreg32(reg & ~(1u << bit), REG_RESET_BANK(bank));
114	}
