116	static void reset_deassert(unsigned int id)
117	{
118	  unsigned int bank = id / 32;
119	  unsigned int bit = id % 32;
120	  uint32_t reg = getreg32(REG_RESET_BANK(bank));
121	
122	  putreg32(reg | (1u << bit), REG_RESET_BANK(bank));
123	}
