126	{
127	  unsigned int bank = id / 32;
128	  unsigned int bit = id % 32;
129	  uintptr_t addr = SG2000_CLKGEN_BASE + bank * 4;
130	  uint32_t reg = getreg32(addr);
131	
132	  putreg32(reg | (1u << bit), addr);
133	}
