135	/****************************************************************************
136	 * Private Functions - D-Cache Operations (T-Head C906)
137	 *
138	 * The C906 has a 32KB 4-way set-associative D-Cache with 64-byte cache
139	 * lines using PIPT (Physical Index + Physical Tag).  DDR memory
140	 * (0x80000000-0xC0000000) is mapped as cacheable via MMU.  DMA
141	 * descriptors and buffers allocated from the kernel heap are therefore
142	 * cacheable, and explicit cache maintenance is REQUIRED before any DMA
143	 * engine access.
144	 *
145	 * The Synopsys DWMAC DMA engine is NOT cache-coherent on this SoC.
146	 *
147	 * T-Head custom instructions (from CV181x/SG2002 TRM):
148	 *   dcache.cpa  rs1  (0x0295000b)  – Clean (write back) by physical addr
149	 *   dcache.ipa  rs1  (0x02a5000b)  – Invalidate by physical addr
150	 *   dcache.cipa rs1  (0x02b5000b)  – Clean + Invalidate by physical addr
151	 *   sync.s           (0x01b0000b)  – Cache operation sync barrier (NOT standard sync 0x0190000b)
152	 ****************************************************************************/
153	
154	static void dcache_clean_range(uintptr_t start, uintptr_t end)
155	{
156	  register uintptr_t i asm("a0") = start & ~(64 - 1);
157	
158	  for (; i < end; i += 64)
159	    {
160	      asm volatile (".long 0x0295000b" ::: "memory");  /* dcache.cpa a0 */
161	    }
162	
163	  asm volatile (".long 0x01b0000b" ::: "memory");      /* sync.s – T-Head C906 cache sync */
164	}
165	
166	static void dcache_invalidate_range(uintptr_t start, uintptr_t end)
167	{
168	  register uintptr_t i asm("a0") = start & ~(64 - 1);
169	
170	  for (; i < end; i += 64)
171	    {
172	      asm volatile (".long 0x02a5000b" ::: "memory");  /* dcache.ipa a0 */
173	    }
174	
175	  asm volatile (".long 0x01b0000b" ::: "memory");      /* sync.s – T-Head C906 cache sync */
176	}
177	
178	static void dcache_flush_range(uintptr_t start, uintptr_t end)
179	{
180	  register uintptr_t i asm("a0") = start & ~(64 - 1);
181	
182	  for (; i < end; i += 64)
183	    {
184	      asm volatile (".long 0x02b5000b" ::: "memory");  /* dcache.cipa a0 */
185	    }
186	
187	  asm volatile (".long 0x01b0000b" ::: "memory");      /* sync.s – T-Head C906 cache sync */
188	}
