194	static void gmac_clock_enable(void)
195	{
196	  uint32_t reg;
197	
198	  /* Enable GMAC0 clocks: clk_500m_eth0 + clk_axi4_eth0 */
199	
200	  reg = getreg32(REG_CLK_EN_0);
201	  reg |= CLK_EN_ETH0_500M | CLK_EN_ETH0_AXI4;
202	  putreg32(reg, REG_CLK_EN_0);
203	
204	  /* Deassert clock-domain resets used by the CVITEK clock-reset
205	   * controller.  Do not confuse these IDs with the main reset-controller
206	   * IDs at 0x03003000.
207	   */
208	
209	  clk_reset_deassert(CLK_RST_500M_ETH0);
210	  clk_reset_deassert(CLK_RST_AXI_ETH0);
211	
212	  /* Release the main reset-controller lines for GMAC and internal EPHY.
213	   * The Linux CVITEK reset driver deasserts by setting the corresponding
214	   * bit in the reset bank.
215	   */
216	
217	  reset_assert(RST_ETH0);
218	  reset_assert(RST_ETHPHY);
219	  reset_assert(RST_ETHPHYRST_APB);
220	  up_udelay(10);
221	  reset_deassert(RST_ETHPHYRST_APB);
222	  reset_deassert(RST_ETHPHY);
223	  reset_deassert(RST_ETH0);
224	  up_udelay(10);
225	
226	  syslog(LOG_INFO, "sg2000_eth: GMAC clocks enabled, CLK_EN_0=0x%08" PRIX32
227	         " RESET0=0x%08" PRIX32 " RESET3=0x%08" PRIX32 "\n",
228	         getreg32(REG_CLK_EN_0), getreg32(REG_RESET_BANK(0)),
229	         getreg32(REG_RESET_BANK(3)));
230	}
