236	static int dma_soft_reset(uintptr_t gmac_base)
237	{
238	  uint32_t val;
239	  int timeout = 100000;
240	
241	  val = getreg32(gmac_base + DMA_BUS_MODE);
242	  syslog(LOG_INFO, "sg2000_eth: DMA reset begin bus_mode=0x%08" PRIX32
243	         "\n", val);
244	  putreg32(val | DMA_SFT_RESET, gmac_base + DMA_BUS_MODE);
245	
246	  do
247	    {
248	      val = getreg32(gmac_base + DMA_BUS_MODE);
249	      if (!(val & DMA_SFT_RESET))
250	        {
251	          return 0;
252	        }
253	
254	      up_udelay(10);
255	    }
256	  while (--timeout > 0);
257	
258	  syslog(LOG_ERR, "sg2000_eth: DMA reset timeout bus_mode=0x%08" PRIX32
259	         " hw_feature0=0x%08" PRIX32 "\n",
260	         getreg32(gmac_base + DMA_BUS_MODE),
261	         getreg32(gmac_base + GMAC_HW_FEATURE0));
262	  return -1;
263	}
