412	static void ephy_hardware_reset(uintptr_t phy_base, uintptr_t phy_top)
413	{
414	  uint32_t apb_id1;
415	  uint32_t apb_id2;
416	
417	  ephy_led_pinmux();
418	
419	  /* Minimal EPHY init sequence, matches Linux bm_eth_reset_phy() in
420	   * dwmac-cvitek.c and U-Boot cv181x_ephy_id_init() in board.c.
421	   * This ONLY releases resets and programs the PHY ID — it does NOT
422	   * run the full analog tuning sequence.  The full tuning (which
423	   * accesses internal pages and starts auto-negotiation) must run
424	   * AFTER the MDIO interface is confirmed operational, just as
425	   * Linux does in cv182xa_phy_config_init() -> config_init callback.
426	   */
427	
428	  /* Select APB interface to access EPHY registers */
429	
430	  putreg32(0x0001, phy_top + 0x4);
431	
432	  /* Release shutdown */
433	
434	  putreg32(0x0900, phy_top);
435	
436	  /* Release dig_rst_n — enables MII register access via APB */
437	
438	  putreg32(0x0904, phy_top);
439	
440	  /* Switch to Page 5 for ANA init */
441	
442	  putreg32(0x0500, phy_base + 0x7c);
443	
444	  /* ANA_PD (power-down release) */
445	
446	  putreg32(0x0c00, phy_base + 0x40);
447	
448	  /* ANA_EN */
449	
450	  putreg32(0x0c7e, phy_base + 0x40);
451	  up_mdelay(1);
452	
453	  /* Release ana_rst_n */
454	
455	  putreg32(0x0906, phy_top);
456	  putreg32(0x0500, phy_base + 0x7c);
457	
458	  /* Program PHY ID into EPHY registers (so MDIO can discover it) */
459	
460	  putreg32(0x0043, phy_base + 0x08);  /* PHY_ID_HIGH */
461	  putreg32(0x5649, phy_base + 0x0c);  /* PHY_ID_LOW */
462	
463	  apb_id1 = getreg32(phy_base + 0x08) & 0xffff;
464	  apb_id2 = getreg32(phy_base + 0x0c) & 0xffff;
465	  syslog(LOG_INFO, "sg2000_eth: EPHY APB PHYID=0x%04" PRIX32
466	         "%04" PRIX32 "\n", apb_id1, apb_id2);
467	
468	  /* Switch control to MDIO (GMAC) so the DWMAC4 MDIO controller can
469	   * discover and communicate with the PHY.
470	   */
471	
472	  putreg32(0x0000, phy_top + 0x4);
473	  up_mdelay(10);
474	
475	  syslog(LOG_INFO, "sg2000_eth: EPHY init done top=0x%08" PRIX32
476	         " sel=0x%08" PRIX32 "\n",
477	         getreg32(phy_top), getreg32(phy_top + 0x4));
478	}
479	
480	/****************************************************************************
481	 * Name: ephy_full_tuning
482	 *
483	 * Description:
484	 *   Run the full CV182XA analog tuning sequence via APB, then switch back
485	 *   to MDIO control.  Matches Linux cv182xa_phy_config_init().
486	 *   MUST be called AFTER MDIO is confirmed operational, as it accesses
487	 *   internal pages and starts auto-negotiation which can interfere with
488	 *   MDIO if run before the MDIO interface is active.
489	 *
490	 ****************************************************************************/
491	
492	static void ephy_full_tuning(uintptr_t phy_base, uintptr_t phy_top)
493	{
494	  /* ephy_full_analog_init expects APB mode; caller ensures MDIO is working
495	   * before we switch to APB for tuning.
496	   */
497	
498	  putreg32(0x0001, phy_top + 0x4);
499	  ephy_full_analog_init(phy_base, phy_top);
500	
501	  /* ephy_full_analog_init ends with:
502	   *   page 0 + autoneg start (0x090e) + force full-duplex
503	   * Switch control back to MDIO so the GMAC can manage the PHY.
504	   */
505	
506	  putreg32(0x0000, phy_top + 0x4);
507	  up_mdelay(10);
508	
509	  syslog(LOG_INFO, "sg2000_eth: EPHY full tuning done, top=0x%08" PRIX32
510	         " sel=0x%08" PRIX32 "\n",
511	         getreg32(phy_top), getreg32(phy_top + 0x4));
512	}
513	
514	/* SG2000/CV181x uses the TRM (Technical Reference Manual) Chapter 18
515	 * legacy GMAC MDIO layout at offsets 0x10/0x14.  The standard DWMAC4
516	 * MDIO controller at 0x200/0x204 is not functional on this silicon.
517	 */
518	
519	static uint16_t mdio_read(uintptr_t gmac_base, int phy_addr, int reg)
520	{
521	  uint32_t cmd;
522	  int timeout = 10000;
523	
524	  do
525	    {
526	      if (!(getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR) &
527	            LEGACY_GMAC_MDIO_BUSY))
528	        {
529	          break;
530	        }
531	
532	      up_udelay(1);
533	    }
534	  while (--timeout > 0);
535	
536	  if (timeout <= 0)
537	    {
538	      return 0xffff;
539	    }
540	
541	  putreg32(0, gmac_base + LEGACY_GMAC_MDIO_DATA);
542	
543	  cmd = (((uint32_t)phy_addr & 0x1f) << LEGACY_GMAC_MDIO_PHY_SHIFT) |
544	        (((uint32_t)reg & 0x1f) << LEGACY_GMAC_MDIO_REG_SHIFT) |
545	        LEGACY_GMAC_MDIO_CR_250_300M | LEGACY_GMAC_MDIO_BUSY;
546	  putreg32(cmd, gmac_base + LEGACY_GMAC_MDIO_ADDR);
547	
548	  timeout = 10000;
549	  do
550	    {
551	      if (!(getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR) &
552	            LEGACY_GMAC_MDIO_BUSY))
553	        {
554	          return getreg32(gmac_base + LEGACY_GMAC_MDIO_DATA) & 0xffff;
555	        }
556	
557	      up_udelay(1);
558	    }
559	  while (--timeout > 0);
560	
561	  return 0xffff;
562	}
563	
564	static void mdio_write(uintptr_t gmac_base, int phy_addr, int reg,
565	                       uint16_t data)
566	{
567	  uint32_t cmd;
568	  int timeout = 10000;
569	
570	  putreg32(data, gmac_base + LEGACY_GMAC_MDIO_DATA);
571	  cmd = (((uint32_t)phy_addr & 0x1f) << LEGACY_GMAC_MDIO_PHY_SHIFT) |
572	        (((uint32_t)reg & 0x1f) << LEGACY_GMAC_MDIO_REG_SHIFT) |
573	        LEGACY_GMAC_MDIO_CR_250_300M | LEGACY_GMAC_MDIO_WRITE |
574	        LEGACY_GMAC_MDIO_BUSY;
575	  putreg32(cmd, gmac_base + LEGACY_GMAC_MDIO_ADDR);
576	
577	  do
578	    {
579	      if (!(getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR) &
580	            LEGACY_GMAC_MDIO_BUSY))
581	        {
582	          break;
583	        }
584	
585	      up_udelay(1);
586	    }
587	  while (--timeout > 0);
588	}
589	
590	static int mdio_verify_phy(uintptr_t gmac_base)
591	{
592	  uint16_t id1 = mdio_read(gmac_base, 0, 2);
593	  uint16_t id2 = mdio_read(gmac_base, 0, 3);
594	  uint32_t phy_id = ((uint32_t)id1 << 16) | id2;
595	
596	  syslog(LOG_INFO, "sg2000_eth: TRM legacy MDIO probe phy_id=0x%08"
597	         PRIX32 "\n", phy_id);
598	
599	  if (id1 == 0xffff || id2 == 0xffff)
600	    {
601	      syslog(LOG_ERR, "sg2000_eth: TRM legacy MDIO timeout reading "
602	             "PHY ID\n");
603	      return -ENODEV;
604	    }
605	
606	  if (phy_id != CVITEK_PHY_ID)
607	    {
608	      syslog(LOG_WARNING, "sg2000_eth: unexpected PHY ID 0x%08" PRIX32
609	             " (expected 0x%08" PRIX32 ")\n", phy_id,
610	             (uint32_t)CVITEK_PHY_ID);
611	    }
612	
613	  return OK;
614	}
