616	/****************************************************************************
617	 * Private Functions - PHY Configuration
618	 ****************************************************************************/
619	
620	static int phy_config_init(struct sg2000_eth_priv_s *priv)
621	{
622	  uint16_t bmsr;
623	  uint16_t bmcr;
624	  uint16_t anlpar;
625	  int timeout;
626	  uint16_t id1 = mdio_read(priv->gmac_base, 0, 2);
627	  uint16_t id2 = mdio_read(priv->gmac_base, 0, 3);
628	  uint32_t phy_id = (id1 << 16) | id2;
629	
630	  syslog(LOG_INFO, "sg2000_eth: PHY ID=0x%08" PRIX32
631	         " expect=0x00435649\n", phy_id);
632	
633	  if (phy_id == 0xffffffff)
634	    {
635	      syslog(LOG_ERR, "sg2000_eth: PHY not responding\n");
636	      return -1;
637	    }
638	
639	  if (phy_id != CVITEK_PHY_ID)
640	    {
641	      syslog(LOG_WARNING, "sg2000_eth: unexpected PHY ID 0x%08" PRIX32
642	             "\n", phy_id);
643	    }
644	
645	  priv->speed = 100;
646	  priv->duplex = 1;
647	
648	  mdio_write(priv->gmac_base, 0, 0, 0x8000);
649	  up_mdelay(10);
650	
651	  timeout = 100;
652	  do
653	    {
654	      bmcr = mdio_read(priv->gmac_base, 0, 0);
655	      if (!(bmcr & 0x8000))
656	        {
657	          break;
658	        }
659	
660	      up_mdelay(1);
661	    }
662	  while (--timeout > 0);
663	
664	  syslog(LOG_INFO, "sg2000_eth: PHY reset done, BMCR=0x%04X\n", bmcr);
665	
666	  mdio_write(priv->gmac_base, 0, 4, 0x01e1);
667	
668	  bmcr = mdio_read(priv->gmac_base, 0, 0);
669	  mdio_write(priv->gmac_base, 0, 0, bmcr | 0x1200);
670	  syslog(LOG_INFO, "sg2000_eth: autoneg start, BMCR=0x%04X\n",
671	         bmcr | 0x1200);
672	
673	  timeout = 50;
674	  do
675	    {
676	      (void)mdio_read(priv->gmac_base, 0, 1);
677	      bmsr = mdio_read(priv->gmac_base, 0, 1);
678	      if ((bmsr & 0x0004) != 0)
679	        {
680	          break;
681	        }
682	
683	      up_mdelay(100);
684	    }
685	  while (--timeout > 0);
686	
687	  if ((bmsr & 0x0004) == 0)
688	    {
689	      syslog(LOG_WARNING, "sg2000_eth: PHY link down, BMSR=0x%04X\n",
690	             bmsr);
691	      priv->link_up = 0;
692	      return OK;
693	    }
694	
695	  anlpar = mdio_read(priv->gmac_base, 0, 5);
696	  syslog(LOG_INFO, "sg2000_eth: PHY link detected, BMSR=0x%04X "
697	         "ANLPAR=0x%04X\n", bmsr, anlpar);
698	
699	  if ((anlpar & 0x0100) != 0)
700	    {
701	      priv->speed = 100;
702	      priv->duplex = 1;
703	    }
704	  else if ((anlpar & 0x0080) != 0)
705	    {
706	      priv->speed = 100;
707	      priv->duplex = 0;
708	    }
709	  else if ((anlpar & 0x0040) != 0)
710	    {
711	      priv->speed = 10;
712	      priv->duplex = 1;
713	    }
714	  else
715	    {
716	      priv->speed = 10;
717	      priv->duplex = 0;
718	    }
719	
720	  priv->link_up = 1;
721	
722	  return 0;
723	}
