725	/****************************************************************************
726	 * Private Functions - DMA Descriptor Management
727	 ****************************************************************************/
728	
729	static int alloc_dma(struct sg2000_eth_priv_s *priv)
730	{
731	  int i;
732	
733	  /* Descriptors and buffers MUST be aligned to the C906 cache-line
734	   * size (64 bytes, ARCH_DMA_MINALIGN) to prevent cache-line sharing
735	   * between adjacent descriptors/buffers, which would cause data
736	   * corruption when CPU and DMA write to different entities that
737	   * share the same cache line.
738	   */
739	
740	  priv->tx_desc = kmm_memalign(64, TX_RING_SIZE *
741	                                sizeof(struct sg2000_dma_desc_s));
742	  priv->rx_desc = kmm_memalign(64, RX_RING_SIZE *
743	                                sizeof(struct sg2000_dma_desc_s));
744	
745	  if (!priv->tx_desc || !priv->rx_desc)
746	    {
747	      return -ENOMEM;
748	    }
749	
750	  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
751	  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
752	
753	  /* For MMU-less or identity-mapped platforms, virtual address = physical.
754	   * TODO: For strict MMU kernel builds, use mm_virt_to_phys().
755	   */
756	
757	  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
758	  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
759	
760	  for (i = 0; i < TX_RING_SIZE; i++)
761	    {
762	      priv->tx_buf[i] = kmm_memalign(64, TX_BUF_SIZE);
763	      if (!priv->tx_buf[i])
764	        {
765	          return -ENOMEM;
766	        }
767	
768	      priv->tx_pkt[i] = NULL;
769	    }
770	
771	  for (i = 0; i < RX_RING_SIZE; i++)
772	    {
773	      priv->rx_buf[i] = kmm_memalign(64, RX_BUF_SIZE);
774	      if (!priv->rx_buf[i])
775	        {
776	          return -ENOMEM;
777	        }
778	    }
779	
780	  return 0;
781	}
782	
783	static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
784	{
785	  uintptr_t base = priv->gmac_base;
786	  int i;
787	  int last;
788	
789	  /* Program DMA Bus Mode register with operational parameters.
790	   * After dma_soft_reset() all bits are cleared; PBL (burst length)
791	   * MUST be programmed for DMA transfers to work.  Use PBL=8
792	   * matching the device tree snps,txpbl/snps,rxpbl settings.
793	   * Set ATDS=1 to match the DWMAC1000 enhanced descriptor control-bit
794	   * layout used by Linux stmmac on CV181x/SG2002.
795	   */
796	
797	  putreg32(DMA_PBL_8 | DMA_FB | DMA_AAL | DMA_ATDS, base + DMA_BUS_MODE);
798	  syslog(LOG_INFO, "sg2000_eth: DMA bus_mode programmed want=0x%08" PRIX32
799	         " read=0x%08" PRIX32 " desc_size=%u\n",
800	         (uint32_t)(DMA_PBL_8 | DMA_FB | DMA_AAL | DMA_ATDS),
801	         getreg32(base + DMA_BUS_MODE),
802	         (unsigned int)sizeof(struct sg2000_dma_desc_s));
803	
804	  /* Initialize TX descriptors.  The last descriptor has TER (End of Ring)
805	   * set so DWMAC1000 wraps back to the ring base address.
806	   */
807	
808	  last = TX_RING_SIZE - 1;
809	  for (i = 0; i < TX_RING_SIZE; i++)
810	    {
811	      priv->tx_desc[i].des0 = (i == last) ? TX_DESC_TER : 0;
812	      priv->tx_desc[i].des1 = 0;
813	      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
814	      priv->tx_desc[i].des3 = 0;
815	      priv->tx_pkt[i] = NULL;
816	    }
817	
818	  /* Flush TX descriptor ring so DMA sees the initialized state */
819	
820	  dcache_clean_range((uintptr_t)priv->tx_desc,
821	                     (uintptr_t)(priv->tx_desc + TX_RING_SIZE));
822	
823	  /* Initialize RX descriptors: set OWN=1 (DMA owns them, can write).
824	   * The last descriptor has RER (End of Ring) set so DWMAC1000 wraps.
825	   */
826	
827	  last = RX_RING_SIZE - 1;
828	  for (i = 0; i < RX_RING_SIZE; i++)
829	    {
830	      priv->rx_desc[i].des0 = DESC_OWN | ((i == last) ? RX_DESC_RER : 0);
831	      priv->rx_desc[i].des1 = RX_BUF_SIZE;
832	      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
833	      priv->rx_desc[i].des3 = 0;
834	    }
835	
836	  /* Flush RX descriptor ring and buffers: DMA will read descriptors
837	   * and write data into the buffers.  Write back the descriptors so
838	   * DMA sees OWN=1.  Also flush RX buffers to ensure any stale cache
839	   * lines are written back before DMA overwrites them.
840	   */
841	
842	  dcache_clean_range((uintptr_t)priv->rx_desc,
843	                     (uintptr_t)(priv->rx_desc + RX_RING_SIZE));
844	
845	  for (i = 0; i < RX_RING_SIZE; i++)
846	    {
847	      dcache_flush_range((uintptr_t)priv->rx_buf[i],
848	                         (uintptr_t)priv->rx_buf[i] + RX_BUF_SIZE);
849	    }
850	
851	  priv->tx_cur = 0;
852	  priv->tx_dirty = 0;
853	  priv->rx_cur = 0;
854	
855	  /* Program DWMAC1000 flat DMA registers.
856	   * DWMAC1000 has NO ring-length registers; wrapping uses TER/RER bits.
857	   * DWMAC1000 has NO channel concept; all registers are flat at 0x1000+.
858	   */
859	
860	  putreg32(priv->tx_desc_phys, base + DMA_TX_BASE_ADDR);
861	  putreg32(priv->rx_desc_phys, base + DMA_RCV_BASE_ADDR);
862	
863	  /* Clear any pending interrupts before enabling them */
864	
865	  putreg32(0x1ffff, base + DMA_STATUS);
866	  putreg32(DMA_INTR_DEFAULT_MASK, base + DMA_INTR_ENA);
867	
868	  syslog(LOG_INFO, "sg2000_eth: DMA init done "
869	         "tx_desc=0x%08" PRIX32 " rx_desc=0x%08" PRIX32
870	         " tx_buf0=0x%08" PRIX32 " rx_buf0=0x%08" PRIX32 "\n",
871	         priv->tx_desc_phys, priv->rx_desc_phys,
872	         (uint32_t)(uintptr_t)priv->tx_buf[0],
873	         (uint32_t)(uintptr_t)priv->rx_buf[0]);
874	}
