876	/****************************************************************************
877	 * Private Functions - MAC and DMA Control
878	 ****************************************************************************/
879	
880	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
881	{
882	  uint32_t hi;
883	  uint32_t lo;
884	
885	  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
886	  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];
887	
888	  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
889	  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
890	}
891	
892	static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
893	{
894	  uintptr_t gmac_base = priv->gmac_base;
895	  uint32_t v;
896	
897	  /* Configure MAC based on PHY negotiation results */
898	
899	  v = GMAC_CORE_INIT;
900	  if (priv->speed == 100)
901	    {
902	      v |= GMAC_CONFIG_FES;   /* 100M */
903	    }
904	
905	  if (priv->duplex)
906	    {
907	      v |= GMAC_CONFIG_DM;    /* Full duplex */
908	    }
909	
910	  putreg32(v, gmac_base + GMAC_CONFIG);
911	
912	  /* Packet filter: pass multicast + broadcast + unicast to us */
913	
914	  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
915	           gmac_base + GMAC_PACKET_FILTER);
916	
917	  /* Clear any pending MAC interrupts */
918	
919	  putreg32(0xffffffff, gmac_base + GMAC_INT_STATUS);
920	
921	  /* Enable MAC interrupts */
922	
923	  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_EN);
924	
925	  /* Flush TX and RX FIFOs before enabling MAC/DMA */
926	
927	  putreg32(0, gmac_base + 0x0048);  /* GMAC_TX_FLUSH */
928	  putreg32(0, gmac_base + 0x004c);  /* GMAC_RX_FLUSH */
929	
930	  /* Enable MAC TX.  In diagnostic mode keep RX disabled to isolate whether
931	   * RX DMA is corrupting memory when traffic arrives.
932	   */
933	
934	  v = getreg32(gmac_base + GMAC_CONFIG);
935	#if SG2000_ETH_DIAG_DISABLE_RX
936	  putreg32((v | GMAC_CONFIG_TE) & ~GMAC_CONFIG_RE, gmac_base + GMAC_CONFIG);
937	#else
938	  putreg32(v | GMAC_CONFIG_TE | GMAC_CONFIG_RE, gmac_base + GMAC_CONFIG);
939	#endif
940	
941	  /* Start TX DMA via DWMAC1000 DMA_CONTROL (CSR6, 0x1018).
942	   * Bit 13 = ST (Start Transmit), Bit 0 = SR (Start Receive).
943	   * Start TX first; RX will be started after a short delay to avoid
944	   * race conditions where RX DMA tries to use descriptors before
945	   * the TX path is fully ready.
946	   */
947	
948	  v = getreg32(gmac_base + DMA_CONTROL);
949	  putreg32(v | DMA_CONTROL_ST, gmac_base + DMA_CONTROL);
950	  up_udelay(10);
951	
952	  v = getreg32(gmac_base + DMA_CONTROL);
953	#if SG2000_ETH_DIAG_DISABLE_RX
954	  putreg32(v & ~DMA_CONTROL_SR, gmac_base + DMA_CONTROL);
955	#else
956	  putreg32(v | DMA_CONTROL_SR, gmac_base + DMA_CONTROL);
957	#endif
958	
959	  syslog(LOG_INFO, "sg2000_eth: DMA started "
960	         "bus_mode=0x%08" PRIX32 " dma_control=0x%08" PRIX32
961	         " dma_status=0x%08" PRIX32 " dma_intr=0x%08" PRIX32
962	         " tx_base=0x%08" PRIX32 " rx_base=0x%08" PRIX32 "\n",
963	         getreg32(gmac_base + DMA_BUS_MODE),
964	         getreg32(gmac_base + DMA_CONTROL),
965	         getreg32(gmac_base + DMA_STATUS),
966	         getreg32(gmac_base + DMA_INTR_ENA),
967	         getreg32(gmac_base + DMA_TX_BASE_ADDR),
968	         getreg32(gmac_base + DMA_RCV_BASE_ADDR));
969	}
