972	 * Private Functions - Doorbell Helpers
973	 ****************************************************************************/
974	
975	static void tx_doorbell(struct sg2000_eth_priv_s *priv)
976	{
977	  /* DWMAC1000: writing ANY value to DMA_XMT_POLL_DEMAND (0x1004)
978	   * triggers the DMA to re-fetch TX descriptors from the ring.
979	   */
980	
981	  putreg32(0, priv->gmac_base + DMA_XMT_POLL_DEMAND);
982	}
983	
984	static void rx_doorbell(struct sg2000_eth_priv_s *priv)
985	{
986	  /* DWMAC1000: writing ANY value to DMA_RCV_POLL_DEMAND (0x1008)
987	   * triggers the DMA to re-fetch RX descriptors from the ring.
988	   */
989	
990	  putreg32(0, priv->gmac_base + DMA_RCV_POLL_DEMAND);
991	}
