993	/****************************************************************************
994	 * Private Functions - Hardware Transmit
995	 ****************************************************************************/
996	
997	static int hw_transmit(struct sg2000_eth_priv_s *priv,
998	                       const uint8_t *data, int len)
999	{
1000	  unsigned int idx = priv->tx_cur;
1001	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
1002	  irqstate_t flags;
1003	
1004	  /* Check if the ring is full */
1005	
1006	  if (desc->des0 & DESC_OWN)
1007	    {
1008	      return -EBUSY;
1009	    }
1010	
1011	  /* Copy data to DMA TX buffer */
1012	
1013	  memcpy(priv->tx_buf[idx], data, len);
1014	
1015	  /* Write back the TX buffer so DMA can see the packet data.
1016	   * Without this, the CPU's cache may hold dirty lines that the
1017	   * non-coherent DMA engine cannot see.
1018	   */
1019	
1020	  dcache_clean_range((uintptr_t)priv->tx_buf[idx],
1021	                     (uintptr_t)priv->tx_buf[idx] + len);
1022	
1023	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
1024	  desc->des1 = len;
1025	
1026	  /* DWMAC1000 enhanced TX descriptor layout with ATDS=1:
1027	   *   TDES0: OWN + FS/LS/IC + TER
1028	   *   TDES1: buffer sizes
1029	   */
1030	
1031	  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
1032	               ((idx == (TX_RING_SIZE - 1)) ? TX_DESC_TER : 0);
1033	
1034	  /* Write back the descriptor so DMA sees OWN=1 and the buffer address.
1035	   * The fence ensures the stores are ordered before the doorbell write.
1036	   */
1037	
1038	  dcache_clean_range((uintptr_t)desc,
1039	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1040	  __asm__ volatile ("fence w,w" ::: "memory");
1041	
1042	  flags = up_irq_save();
1043	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
1044	  tx_doorbell(priv);
1045	  up_irq_restore(flags);
1046	
1047	  syslog(LOG_INFO, "sg2000_eth: TX %u bytes, desc[%u] des0=0x%08" PRIX32
1048	         " des1=0x%08" PRIX32 " des2=0x%08" PRIX32
1049	         " dma_status=0x%08" PRIX32 "\n",
1050	         len, idx, desc->des0, desc->des1, desc->des2,
1051	         getreg32(priv->gmac_base + DMA_STATUS));
1052	
1053	  return 0;
1054	}
1055	
1056	/****************************************************************************
1057	 * Private Functions - TX Cleanup (called from ISR on TX complete)
1058	 ****************************************************************************/
1059	
1060	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
1061	{
1062	  irqstate_t flags = up_irq_save();
1063	
1064	  while (priv->tx_dirty != priv->tx_cur)
1065	    {
1066	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
1067	
1068	      /* Invalidate the descriptor cache line so we read the status
1069	       * that DMA wrote back, not stale cached data.
1070	       */
1071	
1072	      dcache_invalidate_range((uintptr_t)desc,
1073	                              (uintptr_t)desc +
1074	                              sizeof(struct sg2000_dma_desc_s));
1075	
1076	      if (desc->des0 & DESC_OWN)
1077	        {
1078	          /* Still owned by DMA, stop */
1079	
1080	          break;
1081	        }
1082	
1083	      /* Check for TX errors */
1084	
1085	      if (desc->des0 & TX_DESC_ES)
1086	        {
1087	          nerr("ERROR: TX error, status=0x%08" PRIX32 "\n", desc->des0);
1088	        }
1089	
1090	      /* Free the netpkt if we have one tracked for this slot */
1091	
1092	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
1093	        {
1094	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
1095	          priv->tx_pkt[priv->tx_dirty] = NULL;
1096	
1097	          /* Notify upper half that TX is done */
1098	
1099	          netdev_lower_txdone(&priv->dev);
1100	        }
1101	
1102	      /* Release descriptor: clear des0 so it can be reused. */
1103	
1104	      desc->des0 = 0;
1105	
1106	      /* Write back the cleared descriptor so DMA doesn't see stale OWN */
1107	
1108	      dcache_clean_range((uintptr_t)desc,
1109	                         (uintptr_t)desc +
1110	                         sizeof(struct sg2000_dma_desc_s));
1111	
1112	      /* Move to next descriptor */
1113	
1114	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
1115	    }
1116	
1117	  up_irq_restore(flags);
1118	}
1119	
1120	/****************************************************************************
1121	 * Private Functions - ISR
1122	 ****************************************************************************/
1123	
1124	static int sg2000_eth_isr(int irq, void *context, void *arg)
1125	{
1126	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
1127	  uintptr_t base = priv->gmac_base;
1128	  uint32_t status;
1129	  uint32_t intr_en;
1130	  uint32_t mac;
1131	
1132	  /* Clear MAC interrupts */
1133	
1134	  mac = getreg32(base + GMAC_INT_STATUS);
1135	  if (mac)
1136	    {
1137	      putreg32(mac, base + GMAC_INT_STATUS);
1138	    }
1139	
1140	  /* Read DWMAC1000 DMA Status (CSR5, 0x1014) masked by enabled interrupts */
1141	
1142	  intr_en = getreg32(base + DMA_INTR_ENA);
1143	  status = getreg32(base + DMA_STATUS) & intr_en;
1144	
1145	  if (status & (DMA_STATUS_TI | DMA_STATUS_RI | DMA_STATUS_NIS |
1146	                DMA_STATUS_AIS | DMA_STATUS_FBI | DMA_STATUS_TPS |
1147	                DMA_STATUS_RPS | DMA_STATUS_RBU))
1148	    {
1149	      syslog(LOG_INFO, "sg2000_eth: ISR dma_status=0x%08" PRIX32
1150	             " intr_en=0x%08" PRIX32 " mac_int=0x%08" PRIX32 "\n",
1151	             getreg32(base + DMA_STATUS), intr_en, mac);
1152	    }
1153	
1154	  if (!status)
1155	    {
1156	      return OK;
1157	    }
1158	
1159	  /* Write-1-to-clear the status bits */
1160	
1161	  putreg32(status, base + DMA_STATUS);
1162	
1163	  if (status & DMA_STATUS_NIS)
1164	    {
1165	      /* Normal interrupt */
1166	
1167	      if (status & DMA_STATUS_RI)
1168	        {
1169	          /* RX complete: notify upper half that packets are ready.
1170	           * The upper half will call our receive() callback to get them.
1171	           */
1172	
1173	          netdev_lower_rxready(&priv->dev);
1174	        }
1175	
1176	      if (status & DMA_STATUS_TI)
1177	        {
1178	          /* TX complete: cleanup descriptors and notify upper half */
1179	
1180	          tx_cleanup(priv);
1181	        }
1182	    }
1183	
1184	  if (status & DMA_STATUS_AIS)
1185	    {
1186	      /* Abnormal interrupt */
1187	
1188	      nerr("ERROR: DMA Abnormal: 0x%08" PRIX32 "\n", status);
1189	
1190	      if (status & DMA_STATUS_RBU)
1191	        {
1192	          nerr("ERROR: RX Buffer Unavailable\n");
1193	        }
1194	
1195	      if (status & DMA_STATUS_TPS)
1196	        {
1197	          nerr("ERROR: TX Process Stopped\n");
1198	        }
1199	
1200	      if (status & DMA_STATUS_FBI)
1201	        {
1202	          nerr("ERROR: Fatal Bus Error\n");
1203	        }
1204	    }
1205	
1206	  return OK;
1207	}
