1209	/****************************************************************************
1210	 * Name: netdriver_ifup
1211	 *
1212	 * Description:
1213	 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
1214	 *
1215	 ****************************************************************************/
1216	
1217	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1218	{
1219	  FAR struct sg2000_eth_priv_s *priv =
1220	      (FAR struct sg2000_eth_priv_s *)dev;
1221	  int ret;
1222	
1223	  syslog(LOG_INFO, "sg2000_eth: ifup begin\n");
1224	
1225	  /* Ensure GMAC clocks and resets are configured */
1226	
1227	  gmac_clock_enable();
1228	
1229	  /* Set MAC core init (includes PS=MII mode) before PHY/MDIO operations. */
1230	
1231	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONFIG);
1232	
1233	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1234	  up_mdelay(10);
1235	
1236	  ret = mdio_verify_phy(priv->gmac_base);
1237	  if (ret < 0)
1238	    {
1239	      nerr("ERROR: TRM legacy MDIO PHY not responding: %d\n", ret);
1240	      return ret;
1241	    }
1242	
1243	  syslog(LOG_INFO, "sg2000_eth: TRM legacy MDIO operational "
1244	         "mdio_addr=0x%08" PRIX32 " mdio_data=0x%08" PRIX32 "\n",
1245	         getreg32(priv->gmac_base + LEGACY_GMAC_MDIO_ADDR),
1246	         getreg32(priv->gmac_base + LEGACY_GMAC_MDIO_DATA));
1247	
1248	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1249	
1250	  ret = phy_config_init(priv);
1251	  if (ret < 0)
1252	    {
1253	      nerr("ERROR: PHY init failed: %d\n", ret);
1254	      return ret;
1255	    }
1256	
1257	  ret = dma_soft_reset(priv->gmac_base);
1258	  if (ret < 0)
1259	    {
1260	      syslog(LOG_ERR, "sg2000_eth: DMA reset failed after PHY/MDIO "
1261	             "diagnostics: %d\n", ret);
1262	      return ret;
1263	    }
1264	
1265	  if (priv->tx_desc == NULL || priv->rx_desc == NULL)
1266	    {
1267	      ret = alloc_dma(priv);
1268	      if (ret < 0)
1269	        {
1270	          nerr("ERROR: alloc_dma failed: %d\n", ret);
1271	          return ret;
1272	        }
1273	    }
1274	
1275	  init_desc_and_dma(priv);
1276	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1277	  start_mac_and_dma(priv);
1278	#if SG2000_ETH_DIAG_DISABLE_RX
1279	  syslog(LOG_WARNING, "sg2000_eth: DIAG RX disabled: MAC RX, RX DMA and "
1280	         "RX doorbell are intentionally off\n");
1281	#else
1282	  rx_doorbell(priv);
1283	#endif
1284	
1285	  up_enable_irq(priv->irq);
1286	  netdev_lower_carrier_on(dev);
1287	
1288	  syslog(LOG_INFO, "sg2000_eth: ifup done, %d Mbps %s duplex\n",
1289	         priv->speed, priv->duplex ? "Full" : "Half");
1290	
1291	  return OK;
1292	}
1293	
1294	/****************************************************************************
1295	 * Name: netdriver_ifdown
1296	 *
1297	 * Description:
1298	 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
1299	 *
1300	 ****************************************************************************/
1301	
1302	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1303	{
1304	  FAR struct sg2000_eth_priv_s *priv =
1305	      (FAR struct sg2000_eth_priv_s *)dev;
1306	  uint32_t v;
1307	
1308	  up_disable_irq(priv->irq);
1309	
1310	  /* Stop TX and RX DMA via DWMAC1000 DMA_CONTROL (CSR6, 0x1018).
1311	   * Bit 13 = ST (Start Transmit), Bit 0 = SR (Start Receive).
1312	   */
1313	
1314	  v = getreg32(priv->gmac_base + DMA_CONTROL);
1315	  putreg32(v & ~(DMA_CONTROL_ST | DMA_CONTROL_SR),
1316	           priv->gmac_base + DMA_CONTROL);
1317	
1318	  /* Disable MAC TX/RX */
1319	
1320	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1321	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1322	           priv->gmac_base + GMAC_CONFIG);
1323	
1324	  netdev_lower_carrier_off(dev);
1325	
1326	  ninfo("netdriver_ifdown: interface down\n");
1327	
1328	  return OK;
1329	}
1330	
1331	/****************************************************************************
1332	 * Name: netdriver_transmit
1333	 *
1334	 * Description:
1335	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
1336	 *   The driver takes ownership of the netpkt and MUST free it after TX
1337	 *   completion (or on error).
1338	 *
1339	 *   Returned Value:
1340	 *     OK on success (pkt queued for TX); negated errno on failure.
1341	 *
1342	 ****************************************************************************/
1343	
1344	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1345	                               FAR netpkt_t *pkt)
1346	{
1347	  FAR struct sg2000_eth_priv_s *priv =
1348	      (FAR struct sg2000_eth_priv_s *)dev;
1349	  unsigned int len = netpkt_getdatalen(dev, pkt);
1350	  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
1351	  const uint8_t *data;
1352	  int ret;
1353	
1354	  if (len > SG2000_ETH_BUFSIZE)
1355	    {
1356	      nerr("ERROR: TX packet too large: %u\n", len);
1357	      netpkt_free(dev, pkt, NETPKT_TX);
1358	      return -E2BIG;
1359	    }
1360	
1361	#if SG2000_ETH_DIAG_DROP_TX
1362	  syslog(LOG_WARNING, "sg2000_eth: DIAG dropping TX packet before DMA, "
1363	         "len=%u\n", len);
1364	  netpkt_free(dev, pkt, NETPKT_TX);
1365	  netdev_lower_txdone(dev);
1366	  return OK;
1367	#endif
1368	
1369	  /* Extract data from netpkt.  If fragmented, copy out; else use pointer. */
1370	
1371	  if (netpkt_is_fragmented(pkt))
1372	    {
1373	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1374	      data = tmp_buf;
1375	    }
1376	  else
1377	    {
1378	      data = netpkt_getdata(dev, pkt);
1379	      if (!data)
1380	        {
1381	          nerr("ERROR: netpkt_getdata returned NULL\n");
1382	          netpkt_free(dev, pkt, NETPKT_TX);
1383	          return -EINVAL;
1384	        }
1385	    }
1386	
1387	  /* Send via DMA */
1388	
1389	  ret = hw_transmit(priv, data, len);
1390	  if (ret < 0)
1391	    {
1392	      nerr("ERROR: hw_transmit failed: %d\n", ret);
1393	      netpkt_free(dev, pkt, NETPKT_TX);
1394	      return ret;
1395	    }
1396	
1397	  /* Track this packet: store it so tx_cleanup can free it after DMA done.
1398	   * The tx_cur was already advanced by hw_transmit, so use (tx_cur - 1).
1399	   */
1400	
1401	  {
1402	    irqstate_t flags = up_irq_save();
1403	    unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1404	
1405	    priv->tx_pkt[slot] = pkt;
1406	    up_irq_restore(flags);
1407	  }
1408	
1409	  return OK;
1410	}
1411	
1412	/****************************************************************************
1413	 * Name: netdriver_receive
1414	 *
1415	 * Description:
1416	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1417	 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
1418	 *   NULL if no more packets are available.
1419	 *
1420	 *   Returned Value:
1421	 *     A netpkt_t * containing the received packet, or NULL.
1422	 *
1423	 ****************************************************************************/
1424	
1425	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1426	{
1427	  FAR struct sg2000_eth_priv_s *priv =
1428	      (FAR struct sg2000_eth_priv_s *)dev;
1429	  FAR netpkt_t *pkt = NULL;
1430	  struct sg2000_dma_desc_s *desc;
1431	  uint32_t status;
1432	  int frame_len;
1433	  int ret;
1434	
1435	  /* Check if there is a completed RX descriptor.
1436	   * Invalidate the descriptor cache line first so we read the status
1437	   * that DMA wrote back (OWN bit, frame length), not stale cached data.
1438	   */
1439	
1440	  desc = &priv->rx_desc[priv->rx_cur];
1441	  dcache_invalidate_range((uintptr_t)desc,
1442	                          (uintptr_t)desc +
1443	                          sizeof(struct sg2000_dma_desc_s));
1444	
1445	  if (desc->des0 & DESC_OWN)
1446	    {
1447	      /* DMA still owns it, no packet ready yet.
1448	       * This can happen if rxready was signaled for a previous packet
1449	       * that was already consumed, or in edge cases.
1450	       */
1451	
1452	      return NULL;
1453	    }
1454	
1455	  status = desc->des0;
1456	
1457	  /* Check for errors */
1458	
1459	  if (status & RX_DESC_ES)
1460	    {
1461	      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
1462	      goto refill;
1463	    }
1464	
1465	  /* Get frame length (includes FCS which we strip) */
1466	
1467	  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK) - ETH_FCSSLEN;
1468	
1469	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1470	    {
1471	      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
1472	      goto refill;
1473	    }
1474	
1475	  /* Invalidate the RX data buffer so we read the data that DMA wrote,
1476	   * not stale cached data from a previous use of this buffer.
1477	   */
1478	
1479	  dcache_invalidate_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1480	                          (uintptr_t)priv->rx_buf[priv->rx_cur] +
1481	                          RX_BUF_SIZE);
1482	
1483	  /* Allocate a netpkt for the received data */
1484	
1485	  pkt = netpkt_alloc(dev, NETPKT_RX);
1486	  if (!pkt)
1487	    {
1488	      nerr("ERROR: netpkt_alloc failed\n");
1489	      goto refill;
1490	    }
1491	
1492	  /* Copy data from DMA RX buffer into the netpkt */
1493	
1494	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1495	  if (ret < 0)
1496	    {
1497	      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
1498	      netpkt_free(dev, pkt, NETPKT_RX);
1499	      goto refill;
1500	    }
1501	
1502	  ninfo("RX packet: %d bytes\n", frame_len);
1503	
1504	refill:
1505	  /* Return the descriptor to DMA (set OWN=1).
1506	   * Re-set the buffer address in des2 in case DMA overwrote it,
1507	   * and flush the buffer to ensure clean state before DMA writes.
1508	   * Preserve RER (End of Ring) bit for the last descriptor.
1509	   */
1510	
1511	  desc->des0 = DESC_OWN |
1512	               ((priv->rx_cur == (RX_RING_SIZE - 1)) ? RX_DESC_RER : 0);
1513	  desc->des1 = RX_BUF_SIZE;
1514	  desc->des2 = (uint32_t)(uintptr_t)priv->rx_buf[priv->rx_cur];
1515	
1516	  /* Flush the RX buffer before handing it back to DMA:
1517	   * write back + invalidate so the buffer is clean for DMA to write into.
1518	   */
1519	
1520	  dcache_flush_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1521	                     (uintptr_t)priv->rx_buf[priv->rx_cur] + RX_BUF_SIZE);
1522	
1523	  /* Write back the descriptor so DMA sees OWN=1 and the new buffer */
1524	
1525	  dcache_clean_range((uintptr_t)desc,
1526	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1527	
1528	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1529	  rx_doorbell(priv);
1530	
1531	  return pkt;
1532	}
