1534	/****************************************************************************
1535	 * Private Data - Operations Structure
1536	 *
1537	 * The netdev_ops_s maps our callbacks to the OpenVela lowerhalf API.
1538	 ****************************************************************************/
1539	
1540	static const struct netdev_ops_s g_ops =
1541	{
1542	  netdriver_ifup,     /* ifup */
1543	  netdriver_ifdown,   /* ifdown */
1544	  netdriver_transmit, /* transmit */
1545	  netdriver_receive   /* receive */
1546	  /* addmac, rmmac, ioctl, reclaim are not implemented for this simple
1547	   * Ethernet MAC driver.  They are only required for Wi-Fi or advanced
1548	   * filtering scenarios.
1549	   */
1550	};
