1556	/****************************************************************************
1557	 * Name: sg2000_eth_initialize
1558	 *
1559	 * Description:
1560	 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
1561	 *   network stack as a netdev_lowerhalf_s device.
1562	 *
1563	 *   Called from board_late_initialize() during system bringup.
1564	 *
1565	 ****************************************************************************/
1566	
1567	int sg2000_eth_initialize(void)
1568	{
1569	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1570	  FAR struct netdev_lowerhalf_s *dev = &priv->dev;
1571	  int ret;
1572	
1573	  if (g_eth_initialized)
1574	    {
1575	      ninfo("SG2000 Ethernet driver already initialized\n");
1576	      return OK;
1577	    }
1578	
1579	  memset(priv, 0, sizeof(*priv));
1580	  priv->gmac_base = SG2000_GMAC_BASE;
1581	  priv->phy_base = SG2000_EPHY_BASE;
1582	  priv->phy_top = SG2000_EPHY_TOP;
1583	
1584	  /* Set a test MAC address (should be replaced with eFuse/OTP value) */
1585	
1586	  priv->mac_addr[0] = 0x02;
1587	  priv->mac_addr[1] = 0x00;
1588	  priv->mac_addr[2] = 0x00;
1589	  priv->mac_addr[3] = 0x00;
1590	  priv->mac_addr[4] = 0x00;
1591	  priv->mac_addr[5] = 0x01;
1592	
1593	  memcpy(dev->netdev.d_mac.ether.ether_addr_octet, priv->mac_addr,
1594	         IFHWADDRLEN);
1595	
1596	  dev->quota[NETPKT_TX] = TX_RING_SIZE / 2;
1597	  dev->quota[NETPKT_RX] = RX_RING_SIZE / 2;
1598	  dev->ops              = &g_ops;
1599	
1600	  priv->irq = SG2000_IRQ_GMAC;
1601	
1602	  ret = netdev_lower_register(dev, NET_LL_ETHERNET);
1603	  if (ret < 0)
1604	    {
1605	      nerr("ERROR: netdev_lower_register failed: %d\n", ret);
1606	      return ret;
1607	    }
1608	
1609	  netdev_lower_carrier_off(dev);
1610	  g_eth_initialized = true;
1611	  ninfo("SG2000 Ethernet driver registered as eth0 (lowerhalf)\n");
1612	
1613	  gmac_clock_enable();
1614	
1615	  ret = irq_attach(priv->irq, sg2000_eth_isr, priv);
1616	  if (ret < 0)
1617	    {
1618	      nerr("ERROR: irq_attach failed: %d\n", ret);
1619	      return OK;
1620	    }
1621	
1622	  up_enable_irq(priv->irq);
1623	  ninfo("IRQ %d enabled\n", priv->irq);
1624	
1625	  return OK;
1626	}
